    TimelineAuthoringCommand::MoveMarker { marker, tick } => { let item = doc.markers.iter_mut().find(|item| &item.id == marker).ok_or_else(|| TimelineAuthoringError::MissingTarget(marker.to_string()))?; item.tick = *tick; }
